<?php
 namespace Pterodactyl\Services\Dezerx\Staff; use Carbon\CarbonInterface; use Illuminate\Support\Facades\Log; use Pterodactyl\Jobs\Dezerx\SendStaffWebhook; use Pterodactyl\Models\Dezerx\StaffRequest; use Pterodactyl\Models\User; use Pterodactyl\Notifications\Dezerx\StaffUpdate; use Throwable; class StaffNotify { private const BLUE = 5793266; private const GREEN = 5763719; private const RED = 15548997; private const AMBER = 16705372; private const GREY = 10070709; public static function opened(StaffRequest $request): void { $target = $request->target; if ($target !== null) { self::mail($target, 'staff-request-opened', [ 'name' => $target->name, 'server' => self::serverName($request), 'owner' => self::ownerName($request), 'reason' => self::text($request->reason, 500), 'until' => self::duration($request->duration_minutes), ], self::staffUrl()); } self::webhook($request, 'opened', $target === null ? 'New support request' : 'Support asked for by name', self::BLUE, [ 'Asked for' => $target === null ? 'Anybody in the queue' : $target->username, 'Access' => self::duration($request->duration_minutes), 'Scope' => StaffPresets::LABELS[$request->scope] ?? $request->scope, ]); } public static function asked(StaffRequest $request): void { $owner = self::owner($request); self::mail($owner, 'staff-request-waiting', [ 'name' => $owner->name, 'server' => self::serverName($request), 'staff' => self::staffName($request), 'reason' => self::text($request->reason, 500), 'until' => self::duration($request->duration_minutes), ], self::serverUrl($request)); self::webhook($request, 'opened', 'Staff asked an owner for access', self::BLUE, [ 'Staff' => self::staffName($request), 'Access' => self::duration($request->duration_minutes), ]); } public static function claimed(StaffRequest $request): void { $owner = self::owner($request); self::mail($owner, 'staff-request-claimed', [ 'name' => $owner->name, 'server' => self::serverName($request), 'staff' => self::staffName($request), 'until' => self::duration($request->duration_minutes), ], self::serverUrl($request)); self::webhook($request, 'claimed', 'Request taken on, waiting to be let in', self::AMBER, [ 'Staff' => self::staffName($request), ]); } public static function granted(StaffRequest $request): void { $owner = self::owner($request); $staff = $request->staff; $until = self::until($request->expires_at); self::mail($owner, 'staff-access-granted', [ 'name' => $owner->name, 'server' => self::serverName($request), 'staff' => self::staffName($request), 'until' => $until, ], self::serverUrl($request)); if ($staff !== null) { self::mail($staff, 'staff-access-granted', [ 'name' => $staff->name, 'server' => self::serverName($request), 'staff' => $staff->username, 'until' => $until, ], self::staffUrl()); } self::webhook($request, 'granted', 'Support access started', self::GREEN, [ 'Staff' => self::staffName($request), 'Ends' => $until, ]); } public static function declined(StaffRequest $request): void { $owner = self::owner($request); self::mail($owner, 'staff-request-declined', [ 'name' => $owner->name, 'server' => self::serverName($request), 'reason' => self::reasonOrNothing($request->decline_reason), ], self::serverUrl($request)); self::webhook($request, 'declined', 'Request declined by staff', self::RED, [ 'Staff' => self::staffName($request), 'Reason' => self::reasonOrNothing($request->decline_reason), ]); } public static function denied(StaffRequest $request): void { $staff = $request->staff; if ($staff !== null) { self::mail($staff, 'staff-request-declined', [ 'name' => $staff->name, 'server' => self::serverName($request), 'reason' => self::reasonOrNothing($request->decline_reason), ], self::staffUrl()); } self::webhook($request, 'declined', 'Request turned down by the owner', self::RED, [ 'Reason' => self::reasonOrNothing($request->decline_reason), ]); } public static function cancelled(StaffRequest $request): void { $staff = $request->staff; if ($staff !== null) { self::mail($staff, 'staff-request-declined', [ 'name' => $staff->name, 'server' => self::serverName($request), 'reason' => 'The owner called the request off.', ], self::staffUrl()); } self::webhook($request, 'declined', 'Request called off by the owner', self::GREY, []); } public static function withdrawn(StaffRequest $request, User $staff): void { $owner = self::owner($request); self::mail($owner, 'staff-access-handed-back', [ 'name' => $owner->name, 'server' => self::serverName($request), 'staff' => $staff->username, 'note' => 'They stepped back before being let in.', ], self::serverUrl($request)); self::webhook($request, 'resigned', 'Request back in the queue', self::AMBER, [ 'Stepped away' => $staff->username, ]); } public static function resigned(StaffRequest $request, User $staff, string $note): void { $owner = self::owner($request); self::mail($owner, 'staff-access-handed-back', [ 'name' => $owner->name, 'server' => self::serverName($request), 'staff' => $staff->username, 'note' => self::reasonOrNothing($note), ], self::serverUrl($request)); self::webhook($request, 'resigned', 'Session handed back, open for anybody', self::AMBER, [ 'Stepped away' => $staff->username, 'Time left' => self::duration($request->remaining_minutes), 'Note' => self::reasonOrNothing($note), ]); } public static function resolved(StaffRequest $request): void { self::ended($request, 'resolved', 'Session finished', self::GREEN, (string) ($request->resolution ?? '')); } public static function revoked(StaffRequest $request): void { self::ended($request, 'resolved', 'Session ended early', self::GREY, (string) ($request->resolution ?? '')); } public static function expired(StaffRequest $request): void { self::ended($request, 'expired', 'Session ran out of time', self::GREY, ''); } public static function expiring(StaffRequest $request, int $minutes): void { $staff = $request->staff; $owner = self::owner($request); if ($staff !== null) { self::mail($staff, 'staff-access-expiring', [ 'name' => $staff->name, 'server' => self::serverName($request), 'minutes' => (string) $minutes, ], self::staffUrl()); } self::mail($owner, 'staff-access-expiring', [ 'name' => $owner->name, 'server' => self::serverName($request), 'minutes' => (string) $minutes, ], self::serverUrl($request)); self::webhook($request, 'expiring', 'Session ending soon', self::AMBER, [ 'Staff' => self::staffName($request), 'Minutes left' => (string) $minutes, ]); } public static function message(StaffRequest $request, User $author, string $body): void { self::webhook($request, 'message', 'Somebody wrote in a session', self::BLUE, [ 'From' => $author->username, 'Said' => $body, ]); } public static function extensionAsked(StaffRequest $request): void { $owner = self::owner($request); self::mail($owner, 'staff-request-claimed', [ 'name' => $owner->name, 'server' => self::serverName($request), 'staff' => self::staffName($request), 'until' => self::duration($request->extension_minutes), ], self::serverUrl($request)); } public static function extended(StaffRequest $request, int $minutes): void { $staff = $request->staff; if ($staff !== null) { self::mail($staff, 'staff-access-extended', [ 'name' => $staff->name, 'server' => self::serverName($request), 'minutes' => (string) $minutes, 'until' => self::until($request->expires_at), ], self::staffUrl()); } } public static function extensionDenied(StaffRequest $request): void { $staff = $request->staff; if ($staff !== null) { self::mail($staff, 'staff-request-declined', [ 'name' => $staff->name, 'server' => self::serverName($request), 'reason' => 'The owner would rather not add more time.', ], self::staffUrl()); } } private static function ended(StaffRequest $request, string $event, string $title, int $colour, string $note): void { $owner = self::owner($request); $staff = $request->staff; $outcome = self::outcome($request->status); self::mail($owner, 'staff-access-ended', [ 'name' => $owner->name, 'server' => self::serverName($request), 'staff' => self::staffName($request), 'outcome' => $outcome, 'note' => self::reasonOrNothing($note), ], self::serverUrl($request)); if ($staff !== null) { self::mail($staff, 'staff-access-ended', [ 'name' => $staff->name, 'server' => self::serverName($request), 'staff' => $staff->username, 'outcome' => $outcome, 'note' => self::reasonOrNothing($note), ], self::staffUrl()); } self::webhook($request, $event, $title, $colour, [ 'Staff' => self::staffName($request), 'Outcome' => $outcome, 'Note' => self::reasonOrNothing($note), ]); } private static function mail(?User $user, string $template, array $values, string $url): void { if ($user === null || !Staff::flag('notify_email') || trim((string) $user->email) === '') { return; } try { $user->notify(new StaffUpdate($template, $values, $url)); } catch (Throwable $exception) { Log::warning('A support staff email could not be queued.', ['message' => $exception->getMessage()]); } } private static function webhook(StaffRequest $request, string $event, string $title, int $colour, array $fields): void { if (!Staff::webhookEvent($event) || !Staff::hasWebhook()) { return; } $mentions = Staff::mentions(); $lines = []; foreach ($fields as $label => $value) { $text = self::text((string) $value, 200); if ($text !== '') { $lines[] = ['name' => $label, 'value' => $text, 'inline' => true]; } } $content = $mentions['role'] !== null && in_array($event, ['opened', 'resigned'], true) ? '<@&' . $mentions['role'] . '>' : ''; SendStaffWebhook::dispatch([ 'content' => $content, 'allowed_mentions' => [ 'parse' => [], 'roles' => $mentions['role'] !== null ? [$mentions['role']] : [], ], 'embeds' => [[ 'title' => self::text($title, 200), 'description' => self::text((string) $request->reason, 900), 'color' => $colour, 'timestamp' => now()->toAtomString(), 'fields' => array_merge([ ['name' => 'Server', 'value' => self::text(self::serverName($request), 100), 'inline' => true], ['name' => 'Owner', 'value' => self::text(self::ownerName($request), 100), 'inline' => true], ], $lines), 'footer' => ['text' => self::text((string) config('app.name', 'Pterodactyl'), 100)], ]], ]); } private static function owner(StaffRequest $request): User { return $request->server->user; } private static function ownerName(StaffRequest $request): string { return self::owner($request)->username; } private static function staffName(StaffRequest $request): string { if ($request->staff_id === null) { return 'a staff member'; } return $request->staff->username; } private static function serverName(StaffRequest $request): string { return $request->server->name; } private static function serverUrl(StaffRequest $request): string { return url('/server/' . $request->server->uuidShort . '/support'); } private static function staffUrl(): string { return url('/staff'); } private static function outcome(string $status): string { return match ($status) { StaffRequest::RESOLVED => 'the work was finished', StaffRequest::REVOKED => 'it was ended early', StaffRequest::EXPIRED => 'it ran out of time', default => $status, }; } private static function duration(?int $minutes): string { if ($minutes === null || $minutes <= 0) { return 'as long as it takes'; } if ($minutes < 60) { return $minutes . ' minutes'; } $hours = intdiv($minutes, 60); $rest = $minutes % 60; if ($rest === 0) { return $hours === 1 ? 'one hour' : $hours . ' hours'; } return $hours . 'h ' . $rest . 'm'; } private static function until(?CarbonInterface $at): string { if ($at === null) { return 'when the work is done'; } return 'at ' . $at->timezone(config('app.timezone', 'UTC'))->toDayDateTimeString(); } private static function reasonOrNothing(?string $value): string { $text = self::text((string) $value, 500); return $text === '' ? 'Nothing was said.' : $text; } private static function text(string $value, int $limit): string { $clean = preg_replace('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/u', '', trim($value)) ?? ''; $clean = str_replace(['`', '@everyone', '@here'], ['', 'everyone', 'here'], $clean); return mb_substr($clean, 0, $limit); } } 